// Package agent implements the core tool-calling conversation loop.
package agent

import (
	"cmp"
	"context"
	"errors"
	"slices"
	"sync"
)

// Role identifies the sender of a Message in a conversation.
type Role string

const (
	// RoleUser represents a message sent by the end user.
	RoleUser Role = "user"
	// RoleAssistant represents a message generated by the model.
	RoleAssistant Role = "assistant"
	// RoleTool represents the output of a tool invocation.
	RoleTool Role = "tool"
)

// Message represents a single turn in the conversation history.
type Message struct {
	Role       Role
	Content    string
	ToolCallID string
	ToolCalls  []ToolCall
}

// ToolCall represents a model's request to invoke a named tool with JSON input.
type ToolCall struct {
	ID    string
	Name  string
	Input string
}

// ModelResponse holds the model's text output and any requested tool calls.
type ModelResponse struct {
	Content   string
	ToolCalls []ToolCall
}

// ToolSpec describes a tool's name and purpose for the model.
type ToolSpec struct {
	Name        string
	Description string
}

// Model generates assistant responses given conversation history and available tools.
type Model interface {
	Complete(ctx context.Context, msgs []Message, tools []ToolSpec) (ModelResponse, error)
}

// Tool executes a specific capability using a JSON-encoded input string.
type Tool interface {
	Description() string
	Run(ctx context.Context, input string) (string, error)
}

// Run executes the agent loop until the model returns a response with no tool
// calls, an error occurs, or ctx is cancelled. It returns the accumulated
// conversation history.
func Run(ctx context.Context, m Model, tools map[string]Tool, msgs []Message) ([]Message, error) {
	if m == nil {
		return msgs, errors.New("agent: model must not be nil")
	}

	toolSpecs := specs(tools)

	for {
		if err := ctx.Err(); err != nil {
			return msgs, err
		}

		out, err := m.Complete(ctx, msgs, toolSpecs)
		if err != nil {
			return msgs, err
		}
		msgs = append(msgs, assistantMessage(out))

		if len(out.ToolCalls) == 0 {
			return msgs, nil
		}

		results := executeTools(ctx, tools, out.ToolCalls)
		msgs = append(msgs, results...)
	}
}

func executeTools(ctx context.Context, tools map[string]Tool, calls []ToolCall) []Message {
	results := make([]Message, len(calls))
	var wg sync.WaitGroup

	for i, call := range calls {
		wg.Add(1)
		go func() {
			defer wg.Done()
			t, ok := tools[call.Name]
			if !ok {
				results[i] = toolError(call, "unknown tool")
				return
			}
			res, err := t.Run(ctx, call.Input)
			if err != nil {
				results[i] = toolError(call, err.Error())
				return
			}
			results[i] = toolResult(call, res)
		}()
	}

	wg.Wait()
	return results
}

func specs(tools map[string]Tool) []ToolSpec {
	out := make([]ToolSpec, 0, len(tools))
	for name, t := range tools {
		out = append(out, ToolSpec{
			Name:        name,
			Description: t.Description(),
		})
	}
	slices.SortFunc(out, func(a, b ToolSpec) int {
		return cmp.Compare(a.Name, b.Name)
	})
	return out
}

func assistantMessage(out ModelResponse) Message {
	return Message{
		Role:      RoleAssistant,
		Content:   out.Content,
		ToolCalls: out.ToolCalls,
	}
}

func toolResult(call ToolCall, res string) Message {
	return Message{
		Role:       RoleTool,
		ToolCallID: call.ID,
		Content:    res,
	}
}

func toolError(call ToolCall, errMsg string) Message {
	return toolResult(call, "ERROR: "+errMsg)
}
